98	export function looksLikeSecret(value: string): boolean {
99	  if (typeof value !== 'string') {
100	    return false;
101	  }
102	
103	  // OpenAI API keys (sk-...)
104	  if (/^sk-[a-zA-Z0-9-_]{20,}/.test(value)) {
105	    return true;
106	  }
107	
108	  // OpenAI project keys (sk-proj-...)
109	  if (/^sk-proj-[a-zA-Z0-9-_]{20,}/.test(value)) {
110	    return true;
111	  }
112	
113	  // Anthropic keys (sk-ant-...)
114	  if (/^sk-ant-[a-zA-Z0-9-_]{20,}/.test(value)) {
115	    return true;
116	  }
117	
118	  // Generic API key patterns (key-...)
119	  if (/^key-[a-zA-Z0-9]{20,}/.test(value)) {
120	    return true;
121	  }
122	
123	  // Bearer tokens
124	  if (/^Bearer\s+.{20,}/i.test(value)) {
125	    return true;
126	  }
127	
128	  // Basic auth
129	  if (/^Basic\s+.{20,}/i.test(value)) {
130	    return true;
131	  }
132	
133	  // Long base64-like strings (likely tokens/keys) - 64+ chars of alphanumeric
134	  // Using 64 chars to reduce false positives on concatenated IDs, base64 content, or long model names
135	  if (/^[a-zA-Z0-9+/=_-]{64,}$/.test(value)) {
136	    return true;
